import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{r as t,o as s,c as l,a,b as e,d,w as o,e as c}from"./app-89d18e81.js";const r={},h=a("h1",{id:"git-基础指南",tabindex:"-1"},[a("a",{class:"header-anchor",href:"#git-基础指南","aria-hidden":"true"},"#"),e(" Git 基础指南")],-1),u=c(`<p>本指南涵盖了 Git 的日常使用命令，从初始化配置到高级分支操作，旨在帮助你建立清晰的 Git 使用体系。</p><hr><h2 id="_1-环境配置" tabindex="-1"><a class="header-anchor" href="#_1-环境配置" aria-hidden="true">#</a> 1. 环境配置</h2><p>在开始使用 Git 之前，需要先配置用户信息及网络环境。</p><h3 id="_1-1-基础用户信息" tabindex="-1"><a class="header-anchor" href="#_1-1-基础用户信息" aria-hidden="true">#</a> 1.1 基础用户信息</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 设置全局用户名和邮箱</span>
<span class="token function">git</span> config <span class="token parameter variable">--global</span> user.name <span class="token string">&quot;你的名字&quot;</span>
<span class="token function">git</span> config <span class="token parameter variable">--global</span> user.email <span class="token string">&quot;your_email@example.com&quot;</span>

<span class="token comment"># 查看所有配置</span>
<span class="token function">git</span> config <span class="token parameter variable">--list</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-2-网络与安全" tabindex="-1"><a class="header-anchor" href="#_1-2-网络与安全" aria-hidden="true">#</a> 1.2 网络与安全</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 关闭 SSL 认证（在公司内网或自签证书环境下常用）</span>
<span class="token function">git</span> config <span class="token parameter variable">--global</span> http.sslVerify <span class="token string">&quot;false&quot;</span>

<span class="token comment"># 设置代理（解决 GitHub 访问慢的问题）</span>
<span class="token function">git</span> config <span class="token parameter variable">--global</span> https.proxy http://127.0.0.1:7897
<span class="token function">git</span> config <span class="token parameter variable">--global</span> http.proxy http://127.0.0.1:789y

<span class="token comment"># 取消代理</span>
<span class="token function">git</span> config <span class="token parameter variable">--global</span> <span class="token parameter variable">--unset</span> http.proxy
<span class="token function">git</span> config <span class="token parameter variable">--global</span> <span class="token parameter variable">--unset</span> https.proxy
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-3-ssh-连接-github" tabindex="-1"><a class="header-anchor" href="#_1-3-ssh-连接-github" aria-hidden="true">#</a> 1.3 SSH 连接 GitHub</h3><ol><li>生成密钥：<code>ssh-keygen -t rsa -C &quot;your_email@example.com&quot;</code></li><li>获取公钥：查看 <code>~/.ssh/id_rsa.pub</code> 内容。</li><li>添加到 GitHub：<code>Settings -&gt; SSH and GPG keys -&gt; New SSH key</code>。</li></ol><hr><h2 id="_2-基础操作流程" tabindex="-1"><a class="header-anchor" href="#_2-基础操作流程" aria-hidden="true">#</a> 2. 基础操作流程</h2><p>最常用的“三板斧”：添加、提交、推送。</p><h3 id="_2-1-初始化与获取" tabindex="-1"><a class="header-anchor" href="#_2-1-初始化与获取" aria-hidden="true">#</a> 2.1 初始化与获取</h3><ul><li><code>git init</code>: 在当前目录初始化本地仓库。</li><li><code>git clone &lt;url&gt;</code>: 克隆远程项目。 <ul><li><code>git clone -b &lt;branch&gt; &lt;url&gt;</code>: 克隆指定分支。</li><li><code>git clone --recursive &lt;url&gt;</code>: 递归克隆包含子模块的项目。</li></ul></li></ul><h3 id="_2-2-暂存与提交" tabindex="-1"><a class="header-anchor" href="#_2-2-暂存与提交" aria-hidden="true">#</a> 2.2 暂存与提交</h3><ul><li><code>git add .</code>: 将所有改动添加到暂存区。</li><li><code>git commit -m &quot;feat: 描述信息&quot;</code>: 将暂存区改动提交到本地仓库。</li><li><code>git commit --amend</code>: 修改上一次提交（可用于补漏或改注释）。</li></ul><h3 id="_2-3-查看状态与日志" tabindex="-1"><a class="header-anchor" href="#_2-3-查看状态与日志" aria-hidden="true">#</a> 2.3 查看状态与日志</h3><ul><li><code>git status</code>: 查看当前工作区状态。</li><li><code>git log</code>: 查看提交历史。 <ul><li><code>git log --oneline</code>: 一行显示一条记录。</li><li><code>git log -p -2</code>: 查看最后两次提交的具体差异。</li></ul></li></ul><hr><h2 id="_3-远程仓库管理" tabindex="-1"><a class="header-anchor" href="#_3-远程仓库管理" aria-hidden="true">#</a> 3. 远程仓库管理</h2><p>与 GitHub/GitLab 建立连接并进行同步。</p><ul><li><code>git remote add origin &lt;url&gt;</code>: 关联远程仓库。</li><li><code>git remote -v</code>: 查看远程仓库地址。</li><li><code>git remote set-url origin &lt;url&gt;</code>: 修改远程仓库地址。</li><li><code>git pull origin &lt;branch&gt;</code>: 从远程拉取并合并代码。</li><li><code>git push -u origin &lt;branch&gt;</code>: 推送代码并建立追踪关系。</li></ul><hr><h2 id="_4-分支管理" tabindex="-1"><a class="header-anchor" href="#_4-分支管理" aria-hidden="true">#</a> 4. 分支管理</h2><p>分支是 Git 的灵魂，允许你在不干扰主线的情况下并行开发。</p><h3 id="_4-1-基础操作" tabindex="-1"><a class="header-anchor" href="#_4-1-基础操作" aria-hidden="true">#</a> 4.1 基础操作</h3><ul><li><code>git branch</code>: 查看本地分支。</li><li><code>git branch -a</code>: 查看所有分支（含远程）。</li><li><code>git checkout -b &lt;name&gt;</code>: 创建并切换到新分支。</li><li><code>git checkout &lt;name&gt;</code>: 切换到已有分支。</li><li><code>git merge &lt;name&gt;</code>: 合并指定分支到当前分支。</li></ul><h3 id="_4-2-变基-rebase" tabindex="-1"><a class="header-anchor" href="#_4-2-变基-rebase" aria-hidden="true">#</a> 4.2 变基 (Rebase)</h3><p><code>rebase</code> 可以让提交历史变得更加整洁。</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> checkout feature
<span class="token function">git</span> rebase master  <span class="token comment"># 将 feature 分支的改动平移到 master 的最新提交之后</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-删除分支" tabindex="-1"><a class="header-anchor" href="#_4-3-删除分支" aria-hidden="true">#</a> 4.3 删除分支</h3><ul><li><code>git branch -d &lt;name&gt;</code>: 删除本地分支。</li><li><code>git push origin --delete &lt;name&gt;</code>: 删除远程分支。</li></ul><hr><h2 id="_5-撤销与回退" tabindex="-1"><a class="header-anchor" href="#_5-撤销与回退" aria-hidden="true">#</a> 5. 撤销与回退</h2><blockquote><p>[!CAUTION] <code>reset --hard</code> 会丢失所有未提交的修改，请谨慎使用。</p></blockquote><ul><li><code>git reset --hard HEAD</code>: 撤销工作区所有未提交的修改。</li><li><code>git reset --hard &lt;commit-id&gt;</code>: 回退到指定的提交版本。</li><li><code>git checkout -- &lt;file&gt;</code>: 撤销对某个文件的修改（回退到最近一次 add 或 commit 状态）。</li></ul><hr><h2 id="_6-标签-tag" tabindex="-1"><a class="header-anchor" href="#_6-标签-tag" aria-hidden="true">#</a> 6. 标签 (Tag)</h2><p>用于标记发布版本。</p><ul><li><code>git tag</code>: 列出所有标签。</li><li><code>git tag -a v1.0 -m &quot;发布 1.0 版本&quot;</code>: 创建带注释的标签。</li><li><code>git push origin v1.0</code>: 将标签推送到远程。</li><li><code>git tag -d v1.0</code>: 删除本地标签。</li><li><code>git push origin --delete v1.0</code>: 删除远程标签。</li></ul><hr><p>©2026 Entity-now | 持续更新中</p>`,43);function p(g,m){const i=t("RouterLink");return s(),l("div",null,[h,a("blockquote",null,[a("p",null,[e("[!TIP] 仅仅掌握基础命令是不够的。点击查看 "),d(i,{to:"/git/collaboration.html"},{default:o(()=>[e("Git 团队协作与进阶工作流")]),_:1}),e(" 了解如何在团队中高效使用 Git。")])]),u])}const _=n(r,[["render",p],["__file","index.html.vue"]]);export{_ as default};
